# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KIRTASİYEDE VE GİYİM MAĞAZASINDA ALIŞVERİŞ (فِي الْمَكْتَبَةِ وَمَحَلِّ الْمَلَابِسِ)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Kırtasiyede (فِي الْمَكْتَبَةِ / الْقِرْطَاسِيَّةِ)</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• دَفْتَرٌ / كِتَابٌ: Defter / Kitap</text>\n  <text x="44" y="124" font-size="11.5" fill="#334155">• قَلَمٌ / مِمْحَاةٌ: Kalem / Silgi</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">• مِسْطَرَةٌ / مِبْرَاةٌ: Cetvel / Kalemtıraş</text>\n  <text x="44" y="172" font-size="11.5" fill="#334155">• حَقِيبَةٌ / مِقْلَمَةٌ: Çanta / Kalemlik</text>\n  <text x="44" y="196" font-size="11.5" fill="#334155">• قَامُوسٌ / خَرِيطَةٌ: Sözlük / Harita</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">أَنَا بِحَاجَةٍ إِلَى دَفْتَرٍ وَقَلَمٍ</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Giyim Mağazasında (فِي مَحَلِّ الْمَلَابِسِ)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• قَمِيصٌ / بَنْطَلُونٌ: Gömlek / Pantolon</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• فُسْتَانٌ / تَنُّورَةٌ: Elbise / Etek</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• مِعْطَفٌ / سُتْرَةٌ: Palto / Ceket</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">• حِذَاءٌ / جَوْرَبٌ: Ayakkabı / Çorap</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">• حِجَابٌ / قُبَّعَةٌ: Başörtüsü / Şapka</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">أُرِيدُ قَمِيصًا أَبْيَضَ وَحِذَاءً أَسْوَدَ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİYAT SORMA (بِكَمْ هٰذَا؟) VE RENKLER (الْأَلْوَانُ)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Fiyat Sorma ve Pazarlık Kalıpları</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• بِكَمْ هٰذَا الْقَمِيصُ؟ (Bu gömlek kaça?)</text>\n  <text x="44" y="124" font-size="11.5" fill="#334155">• بِكَمْ هٰذِهِ الْحَقِيبَةُ؟ (Bu çanta kaça?)</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">• هٰذَا غَالٍ جِدًّا! (Bu çok pahalı!)</text>\n  <text x="44" y="172" font-size="11.5" fill="#334155">• هٰذَا رَخِيصٌ وَجَمِيلٌ. (Bu ucuz ve güzel.)</text>\n  <text x="44" y="196" font-size="11.5" fill="#334155">• كَمِ الْمَجْمُوعُ؟ (Toplam ne kadar?)</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">الْمَجْمُوعُ تِسْعَ عَشْرَةَ لِيرَةً (Toplam 19 lira)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Renkler (الْأَلْوَانُ: Müzekker / Müennes)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• أَبْيَضُ / بَيْضَاءُ: Beyaz (قَمِيصٌ أَبْيَضُ)</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• أَسْوَدُ / سَوْدَاءُ: Siyah (حَقِيبَةٌ سَوْدَاءُ)</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• أَحْمَرُ / حَمْرَاءُ: Kırmızı (قَلَمٌ أَحْمَرُ)</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">• أَزْرَقُ / زَرْقَاءُ: Mavi (سُتْرَةٌ زَرْقَاءُ)</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">• أَخْضَرُ / خَضْرَاءُ · أَصْفَرُ / صَفْرَاءُ: Yeşil · Sarı</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">أَتُفَضِّلُ الْقَمِيصَ الْأَزْرَقَ أَمِ الْأَبْيَضَ؟</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ALIŞVERİŞ TEMASI GENEL ÖZETİ: SAYILAR, BAĞLAÇLAR VE TİCARET AHLAKI</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">11-19 Arası Sayılar (الْأَعْدَادُ)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• ١١: أَحَدَ عَشَرَ / إِحْدَى عَشْرَةَ</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• ١٢: اِثْنَا عَشَرَ / اِثْنَتَا عَشْرَةَ</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• ١٣-١٩: ثَلَاثَةَ عَشَرَ ... تِسْعَةَ عَشَرَ</text>\n  <text x="40" y="166" font-size="11" fill="#334155">• عَشَرَةُ طُلَّابٍ (10 erkek öğrenci)</text>\n  <text x="40" y="188" font-size="11" fill="#334155">• خَمْسَ عَشْرَةَ لِيرَةً (15 lira)</text>\n  <text x="130" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">بِكَمْ؟ — بِثَمَانِي عَشْرَةَ لِيرَةً</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Temel Bağlaçlar ve Sorular</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• وَ (ve): قَلَمٌ وَدَفْتَرٌ</text>\n  <text x="260" y="120" font-size="11" fill="#334155">• أَوْ (veya): شَايٌ أَوْ حَلِيبٌ</text>\n  <text x="260" y="142" font-size="11" fill="#334155">• أَمْ (yoksa): أَتُفَضِّلُ هٰذَا أَمْ ذٰلِكَ؟</text>\n  <text x="260" y="166" font-size="11" fill="#334155">• ثُمَّ (sonra): خُبْزًا ثُمَّ جُبْنًا</text>\n  <text x="260" y="188" font-size="11" fill="#334155">• هَلْ عِنْدَكَ...؟ (Sende ... var mı?)</text>\n  <text x="350" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">أَنَا بِحَاجَةٍ إِلَى... (İhtiyacım var)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Ticaret ve İnfak İlkeleri</text>\n  <text x="480" y="102" font-size="11" font-weight="bold" fill="#92400e">• اِنْتَبِهْ لِلْكَيْلِ وَالْمِيزَانِ</text>\n  <text x="480" y="120" font-size="10.5" fill="#334155">(Ölçü ve tartıya dikkat et!)</text>\n  <text x="480" y="146" font-size="11" font-weight="bold" fill="#92400e">• اللّٰهُ لَا يُحِبُّ الْمُطَفِّفِينَ</text>\n  <text x="480" y="164" font-size="10.5" fill="#334155">(Allah hile yapanları sevmez.)</text>\n  <text x="480" y="190" font-size="11" font-weight="bold" fill="#92400e">• الْكَاسِبُ حَبِيبُ اللّٰهِ</text>\n  <text x="480" y="208" font-size="10.5" fill="#334155">(Helal kazanan Allah\'ın dostudur.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
